function useKeyboardScroll(){
 const scrollRef=useRef<ScrollView|null>(null),focusedRef=useRef<TextInput|null>(null),scrollY=useRef(0);
 const setScrollRef=useCallback((scroll:ScrollView|null)=>{scrollRef.current=scroll;scrollY.current=0;focusedRef.current=null},[]);
 const reveal=useCallback(()=>{
  if(Platform.OS!=='ios'||!scrollRef.current||!focusedRef.current)return;
  const keyboard=Keyboard.metrics();
  if(!keyboard||keyboard.height<=0)return;
  // Measure after keyboard and layout changes so long forms reveal the active field.
  focusedRef.current.measureInWindow((_x,y,_width,height)=>{
   const overlap=y+height+18-keyboard.screenY;
   if(overlap>0)scrollRef.current?.scrollTo({y:scrollY.current+overlap,animated:true});
  });
 },[]);
 useEffect(()=>{
  if(Platform.OS!=='ios')return;
  const shown=Keyboard.addListener('keyboardDidShow',reveal);
  const changed=Keyboard.addListener('keyboardDidChangeFrame',reveal);
  return()=>{shown.remove();changed.remove()};
 },[reveal]);
 const focus=useCallback((input:TextInput|null)=>{focusedRef.current=input;requestAnimationFrame(reveal)},[reveal]);
 const onLayout=useCallback(()=>{requestAnimationFrame(reveal)},[reveal]);
 const onScroll=useCallback((event:NativeSyntheticEvent<NativeScrollEvent>)=>{scrollY.current=Math.max(0,event.nativeEvent.contentOffset.y)},[]);
 return {scrollRef:setScrollRef,focus,onLayout,onScroll};
}
function KeyboardInput({scrollToFocused,onFocus,...props}:TextInputProps&{scrollToFocused:(input:TextInput|null)=>void}){
 const inputRef=useRef<TextInput|null>(null);
 return <TextInput {...props} ref={inputRef} onFocus={event=>{scrollToFocused(inputRef.current);onFocus?.(event)}}/>;
}
